// resume-app/templates.js - template gallery of the resume editor: developer, classic, creative,
// academic, minimal and blank (sample PDFs and artwork generated by sample/).
//
// Structure: tplKit() (builder helpers) -> six tplBuild*(V) functions, each returning a complete normalised document
// -> the TEMPLATES registry (id, localised name/desc, content languages, build). Most of this file is sample content
// (people, jobs, certificates); only the kit and the blank builder hold logic.
// Why code instead of stored JSON documents: samples need generated assets (avatar SVG, artwork PNG, certificate
// PDFs from sample/), fresh ids per build (two documents from one template never share ids), and they go through the
// same V.newDoc / V.normalizeDoc path as user documents, so a schema change is picked up without migrating JSON.
// V is the product API (viewer.js facade), injected rather than imported to keep this module free of the editor.
import { tplMakePDF } from '../sample/pdf.js';
import { tplBaseKit, tplIcon, tplSampleFiles } from '../sample/kit.js';
import { tplAvatarSVG, tplImageSVG } from '../sample/svg.js';
import { tplImagePNG } from '../sample/png.js';

// Sample PDFs of the resume templates.
const RESUME_PDF = { producer: 'rv resume builder', creator: 'rv resume templates' };
const makePDF = (title, lines) => tplMakePDF(title, lines, RESUME_PDF);

// Helper vocabulary of the builders: L(text) = per-language text map, B(type, props) = block, sec / head / contact /
// tl / skill / lang / kv = shorthand item and block makers, addAtt = attachment registration. `appendix` marks files
// listed in the exported appendix; assets (photos) are embedded but not listed.
/** Resume builder kit: the shared base kit (sample/kit.js) plus resume items; attachments carry `appendix`. */
function tplKit(V, langs) {
  const files = tplSampleFiles(V, { pdf: RESUME_PDF, extra: (o) => ({ appendix: o.appendix !== false && !o.asset }) });
  const K = tplBaseKit(V, langs, files);
  const { L, B, id } = K;
  return Object.assign(K, {
    sec: (title, icons, blocks, extra = {}) =>
      B('section', { title: L(title), icon: tplIcon(V, ...(icons || [])), blocks, ...extra }),
    head: (text, level = 2, icons = [], extra = {}) =>
      B('heading', { text: L(text), level, icon: tplIcon(V, ...icons), ...extra }),
    contact: (kind, value, label) => ({ id: id(), kind, value, href: '', label: L(label || '') }),
    tl: (o) => ({
      id: id(),
      start: o.start || '', end: o.end || '', url: o.url || '',
      title: L(o.title || ''), org: L(o.org || ''), location: L(o.location || ''),
      tags: L(o.tags || ''), html: L(o.html || ''),
    }),
    skill: (name, level, group) => ({ id: id(), name: L(name), level, group: L(group || '') }),
    lang: (name, level, note) => ({ id: id(), name: L(name), level, note: L(note || '') }),
    kv: (k, v) => ({ id: id(), k: L(k), v: L(v) }),
    /** Base document: theme preset vars copied in (as the editor does when picking a preset). */
    doc(o) {
      const d = V.newDoc();
      const now = new Date().toISOString();
      d.name = o.name;
      d.langs = langs.slice();
      d.defaultLang = o.defaultLang || langs[0];
      d.meta = {
        ...(d.meta || {}),
        title: L(o.title), description: L(o.description),
        author: o.author || '', keywords: o.keywords || '', created: now, modified: now,
      };
      // Spread order matters: document defaults, then the preset's vars (as the editor's preset picker does), then
      // template-specific overrides, so a template can tweak a single variable of its preset.
      const preset = V.THEMES && V.THEMES[o.preset]; // o.preset: a template constant, not document data
      d.theme = { ...(d.theme || {}), ...((preset && preset.vars) || {}), preset: o.preset, ...(o.theme || {}) };
      d.layout = { ...(d.layout || {}), type: o.layout, ...(o.layoutOpts || {}) };
      const out = { ...(d.output || {}), ...(o.output || {}) };
      out.appendix = { ...((d.output && d.output.appendix) || {}), ...((o.output && o.output.appendix) || {}) };
      d.output = out;
      d.page = { ...(d.page || {}), ...(o.page || {}) };
      d.regions = { header: [], main: [], side: [] };
      d.attachments = K.atts;
      return d;
    },
  });
}

// Each sample template is one function: content in its content languages (sample person, timeline, skills, files).
