// ===== Template 6: blank starter (in the user's language) =====

const TPL_BLANK_SECTION = {
  en: 'Experience', ru: 'Опыт работы', de: 'Berufserfahrung', fr: 'Expérience professionnelle',
  es: 'Experiencia', uk: 'Досвід роботи', ka: 'სამუშაო გამოცდილება',
};

function tplBuildBlank(V, lang = 'en', opts = {}) {
  // lang comes from the UI (BCP 47-ish check): an unexpected value falls back to English instead of creating a
  // document with a bogus language key. hasOwnProperty guards against keys like "constructor".
  if (typeof lang !== 'string' || !/^[a-z]{2,3}(-[A-Za-z0-9]{1,8})*$/.test(lang)) lang = 'en';
  const secTitle = Object.prototype.hasOwnProperty.call(TPL_BLANK_SECTION, lang) ? TPL_BLANK_SECTION[lang] : TPL_BLANK_SECTION.en;
  const K = tplKit(V, [lang]);
  const { B, L } = K;
  const d = K.doc({
    name: opts.name || 'Untitled resume',
    preset: 'modern',
    layout: 'single',
    layoutOpts: { headerFull: true, sideInSingle: 'after' },
    title: '', description: '',
    output: { appendix: { enabled: true } },
  });
  d.regions.header = [
    B('profile', { name: L(''), title: L(''), summary: L(''), photo: null, align: 'left' }),
    B('contacts', {
      layout: 'inline', icons: true, showLabels: false,
      items: [K.contact('email', ''), K.contact('phone', ''), K.contact('location', '')],
    }),
  ];
  d.regions.main = [
    K.sec({ [lang]: secTitle }, ['briefcase', 'work'], [K.text('')]),
  ];
  return V.normalizeDoc(d);
}

